import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.SetActorMotion{EntityRuntimeID: 300, Velocity: mgl32.Vec3{-0.5, 1.25, 2}, Tick: 130}
GOLDEN = bytes.fromhex("ac02000000bf0000a03f000000408201")

# generated by gophertunnel b8bd735:
# packet.SetActorMotion{EntityRuntimeID: 4294967297, Velocity: mgl32.Vec3{0, 0, 0}, Tick: 4294967296}
WIDE = bytes.fromhex("81808080100000000000000000000000008080808010")

GOLDENS = [
    pytest.param(
        v2225.SetActorMotionPacket(runtime_id=300, motion=v2225.Vec3(x=-0.5, y=1.25, z=2.0), tick=130),
        GOLDEN,
        id="narrow",
    ),
    pytest.param(
        v2225.SetActorMotionPacket(runtime_id=4294967297, motion=v2225.Vec3(x=0.0, y=0.0, z=0.0), tick=4294967296),
        WIDE,
        id="wide-runtime-id-and-tick",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_set_actor_motion_is_packet_40(version):
    assert version.PACKETS[40] is version.SetActorMotionPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_actor_motion_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_actor_motion_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
